  // exactly as much as a curator that never ran.
  let pr_decision = 'n/a', pr_reason = '', pr_curated = false;
  let pr_title = prTitle, pr_body = prBody;
  const m = (r.choices && r.choices[0] && r.choices[0].message) || {};
